(function mergeV05(){
  const byId = new Map(PEOPLE.map(p=>[p.id,p]));
  Object.entries(V05_TOUCHES).forEach(([id,patch])=>{
    const p=byId.get(id); if(!p) return;
    for(const key of ['refs','sourceTags','aliases']){
      if(patch[key]) p[key]=[...new Set([...(p[key]||[]),...patch[key]])];
    }
    for(const [k,v] of Object.entries(patch)) if(!['refs','sourceTags','aliases'].includes(k) && p[k]==null) p[k]=v;
  });
  for(const p of V05_PEOPLE){ if(!byId.has(p.id)){ PEOPLE.push(p); byId.set(p.id,p); } }
  const relKey = r => `${r.from}>${r.to}:${r.relation}:${r.variant?'v':'n'}:${(r.refs||[]).join('|')}`;
  const seen = new Set(RELATIONSHIPS.map(relKey));
  for(const r of V05_RELATIONSHIPS){ const k=relKey(r); if(!seen.has(k)){ RELATIONSHIPS.push(r); seen.add(k); } }
  VIEW_PRESETS.chronicles4={label:'1 Crônicas 4 — Judá e Simeão',ids:V05_GROUPS.chronicles4};
  VIEW_PRESETS.chronicles5={label:'1 Crônicas 5 — Rúben, Gade e Manassés',ids:V05_GROUPS.chronicles5};
  VIEW_PRESETS.levites={label:'1 Crônicas 6 — Levi e sacerdócio',ids:V05_GROUPS.levites};
  VIEW_PRESETS.chronicles7={label:'1 Crônicas 7 — tribos',ids:V05_GROUPS.chronicles7};
  VIEW_PRESETS.benjaminSaul={label:'1 Crônicas 8–9 — Benjamim e Saul',ids:V05_GROUPS.benjaminSaul};
  VIEW_PRESETS.postexilic={label:'Pós-exílio — Esdras/Neemias',ids:V05_GROUPS.postexilic};
})();
